const test = require('node:test');
const assert = require('node:assert/strict');
const { isoStamp } = require('../src/audit-iso.cjs');

test("ordinary dates have UTC Z suffix and milliseconds", () => {
  const date = new Date('2026-07-18T09:02:03.004+08:00');
  const before = date.getTime();
  assert.equal(isoStamp(date), '2026-07-18T01:02:03.004Z');
  assert.equal(date.getTime(), before);
  assert.equal(isoStamp(new Date(0)), '1970-01-01T00:00:00.000Z');
});

test("expanded years are signed six digit years", () => {
  assert.equal(isoStamp(new Date('+010000-01-02T00:00:00.000Z')), '+010000-01-02T00:00:00.000Z');
  assert.equal(isoStamp(new Date('-000001-12-31T00:00:00.000Z')), '-000001-12-31T00:00:00.000Z');
});

test("invalid dates throw instead of serializing to null", () => {
  assert.throws(() => isoStamp(new Date(NaN)), RangeError);
  assert.throws(() => isoStamp(new Date(Infinity)), RangeError);
});

